 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    def runs(row):
        result = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color, start = row[c], c
            while c < w and row[c] == color:
                c += 1
            result.append((color, start, c - start))
        return result

    top, bottom = runs(grid[0]), runs(grid[-1])
    pairs = [(a, b) for a in top for b in bottom
             if a[0] == b[0] and a[2] == b[2]]
    out = [row[:] for row in grid]
    if not pairs:
        return out
    (bar_color, top_start, length), (_, bottom_start, _) = pairs[0]
    shift = bottom_start - top_start
    markers = [(r, c, grid[r][c]) for r in range(1, h - 1)
               for c in range(w) if grid[r][c] not in (bg, bar_color)]
    for r, c, color in markers:
        if top_start <= c < top_start + length:
            # Continue the point's ray to the top edge.
            for rr in range(1, r):
                out[rr][c] = color
            paired = c + shift
        elif bottom_start <= c < bottom_start + length:
            # Continue the point's ray to the bottom edge.
            for rr in range(r + 1, h - 1):
                out[rr][c] = color
            paired = c - shift
        else:
            continue
        # Its translated counterpart spans the open space between the bars.
        if 0 <= paired < w:
            for rr in range(1, h - 1):
                out[rr][paired] = color
        out[r][c] = 4
    return out
