    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def runs(row):
        result = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color, start = row[c], c
            while c < w and row[c] == color:
                c += 1
            result.append((color, start, c - start))
        return result

    matches = [(a, b) for a in runs(grid[0]) for b in runs(grid[-1])
               if a[0] == b[0] and a[2] == b[2]]
    out = [row[:] for row in grid]
    if not matches:
        return out
    (bar, ts, length), (_, bs, _) = matches[0]
    offset = bs - ts
    for r in range(1, h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color == bar:
                continue
            if ts <= c < ts + length:
                # Marker aligns with the top bar: ray points toward the top.
                for rr in range(0, r):
                    if grid[rr][c] != bar:
                        out[rr][c] = color
                paired = c + offset
                # Paired ray extends from the opposite boundary through the grid.
                for rr in range(h):
                    if grid[rr][paired] != bar:
                        out[rr][paired] = color
            elif bs <= c < bs + length:
                # Marker aligns with the bottom bar: ray points toward the bottom.
                for rr in range(r + 1, h):
                    if grid[rr][c] != bar:
                        out[rr][c] = color
                paired = c - offset
                for rr in range(h):
                    if grid[rr][paired] != bar:
                        out[rr][paired] = color
            out[r][c] = 4
    return out
